1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Consolidated duplicate detection for create-owner. All duplicate detection is now expressed through
10	 * the single derived {@link IdentityKey} (@code normalizedTelephone + '|' + (email or empty) + '|' +
11	 * householdId}), replacing the former separate telephone, email and household checks. Runs after the
12	 * telephone and email have been normalized and before the owner is built and saved.
13	 *
14	 * <p>Because the telephone is a component of the key, two members of the same household (same
15	 * {@code householdId}) with different telephones derive different identityKeys and are both allowed;
16	 * the create endpoint rejects a request whose normalized telephone — the identityKey's discriminating
17	 * component — is already used by an existing owner, i.e. an identityKey collision. Existing owners'
18	 * telephones are normalized to E.164 the same way before comparison, so numbers stored in any format
19	 * are matched by their E.164 value. A collision is rejected via {@link DuplicateIdentityException},
20	 * which the global handler turns into a 409.
21	 */
22	public class RejectDuplicateOwner {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DuplicateIdentityException {
26	        String telephone = request.getTelephone();
27	        for (Owner existing : ownerRepository.findAll()) {
28	            if (telephone.equals(TelephoneE164.normalizeOrNull(existing.getTelephone()))) {
29	                throw new DuplicateIdentityException(IdentityKey.of(request.getTelephone(),
30	                        request.getEmail(), request.getLastName(), request.getAddress()));
31	            }
32	        }
33	    }
34	}
