1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Thrown by {@link RejectDuplicateOwner} when a create-owner request's derived {@link IdentityKey}
5	 * collides with an existing owner's. This single check replaces the former separate telephone, email
6	 * and household duplicate checks. Handled globally by {@code DuplicateIdentityExceptionHandler},
7	 * which responds 409.
8	 */
9	public class DuplicateIdentityException extends Exception {
10	
11	    public DuplicateIdentityException(String identityKey) {
12	        super("Owner identityKey already in use by another owner: " + identityKey);
13	    }
14	}
