1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	/**
6	 * Derives an owner's {@code identityKey}: the single value all duplicate detection is now expressed
7	 * through. It is {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the
8	 * telephone is normalized to E.164 the same way as {@link NormalizeTelephone}/{@link TelephoneE164},
9	 * the email is trimmed and lower-cased (empty when absent or blank, the same form as
10	 * {@link NormalizeEmail}), and the household component is {@link HouseholdId} over the last name and
11	 * address. Because the telephone is part of the key, two members of the same household (same
12	 * {@code householdId}) with different telephones derive different identityKeys.
13	 */
14	public final class IdentityKey {
15	
16	    private IdentityKey() {
17	    }
18	
19	    public static String of(String telephone, String email, String lastName, String address) {
20	        String normalizedTelephone = TelephoneE164.normalizeOrNull(telephone);
21	        if (normalizedTelephone == null) {
22	            normalizedTelephone = telephone == null ? "" : telephone.trim();
23	        }
24	        String normalizedEmail = (email == null || email.isBlank())
25	                ? "" : email.trim().toLowerCase(Locale.ROOT);
26	        String householdId = HouseholdId.of(lastName, address);
27	        return normalizedTelephone + "|" + normalizedEmail + "|" + householdId;
28	    }
29	}
